INSERT INTO scenic_spot (id, name, description, longitude, latitude, address, image_url, image_anime_url, region, created_at, updated_at) VALUES
(1, '大明湖', '始建于北魏，历代重修扩建；杜甫、李邕曾游宴，有\"济南名士多\"典故', 117.015833, 36.67, '大明湖景区历下亭', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/大明湖_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(2, '趵突泉', '始建于北魏，宋代始建亭，历代重修；乾隆御封\"天下第一泉\"，为济南三大名胜之一', 117.011667, 36.663056, '趵突泉景区观澜亭', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/趵突泉_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(3, '千佛山', '古称历山，隋代凿佛建寺，历代扩建；佛教名山，济南三大名胜之一，有舜耕传说', 117.008333, 36.643333, '千佛山风景名胜区', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/千佛山_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(4, '华不注山', '春秋已得名，为古济南名山；孤峰刺天，历代画家诗人题咏众多，赵孟頫《鹊华秋色》主角之一', 117.086667, 36.736667, '黄河南岸华山森林公园', NULL, NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(5, '鹊山', '因扁鹊炼丹传说得名，为济南名山；与华不注并称鹊华，为赵孟頫《鹊华秋色》主角之一', 117.016667, 36.75, '黄河北岸鹊山村', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/鹊山_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(6, '汇波楼', '始建于元代，历代重修；汇波晚照为济南八景之一', 117.018056, 36.672222, '大明湖景区汇波楼', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/汇波楼_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(7, '五龙潭', '隋唐已成名泉，历代修整；传说为秦琼故居，泉群汇为深潭', 117.013889, 36.665833, '五龙潭公园', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/五龙潭_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(8, '珍珠泉', '金代已列入名泉志，明清为巡抚衙门驻地；泉沸如浮珍珠，为济南四大名泉之一', 117.016667, 36.666944, '珍珠泉大院', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/珍珠泉_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(9, '黑虎泉', '金代已列入名泉，明代始建石龛；三兽喷黑水，声如虎啸，为济南四大名泉之一', 117.020833, 36.659722, '黑虎泉泉群', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黑虎泉_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(10, '华山', '古称华不注，春秋齐晋鞌之战发生于此；孤峰独秀，为济南胜景', 117.086667, 36.736667, '华不注山', NULL, NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(11, '金线泉', '金代已列入名泉志，清代归并入趵突泉公园；水面有纹如金线，为济南四大名泉之一', 117.012222, 36.662778, '趵突泉公园内', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/金线泉_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(12, '灵岩寺', '始建于东晋，唐代拓建，历代重修；海内四大名刹之首，有千佛殿辟支塔', 116.966667, 36.366667, '泰山西北灵岩寺景区', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/灵岩寺_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(13, '龙洞', '北魏已见记载，为济南东名山；山川幽胜，有龙洞秋风为济南八景之一', 117.116667, 36.683333, '龙洞风景区', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/龙洞_实景_01.jpg', NULL, '济南', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(14, '泰山', '先秦至秦汉：先秦时期已成为五岳之首和政权象征，秦始皇统一六国后，将泰山祭祀仪式变为帝王专有的封禅大典。汉武帝曾先后8次前往岱顶封禅，汉光武帝也进行过一次泰山封禅。\n魏晋南北朝：佛教和道教相继流入泰山，时局动荡使常规祭祀难以开展，临时的非常规祭祀盛行，分裂政权常祭祀泰山以证明统治合法性。\n隋唐宋金：隋代开创泰山祭祀制度，将其纳入政府行政体系；唐代开创泰山封爵制度，并规范祭祀仪式程序。宋代宋真宗前往泰山封禅，此后皇帝不再正式举办封禅大典。金代泰山庙呈现道教化宫观化色彩。这一时期还出现了泰山书院。\n元明清：元代加封泰山为“东岳为天齐大生仁圣帝”；明朝增设管理泰山的官员，文人墨客游览增多并留下墨迹；清朝康熙、乾隆等皇帝都曾前往泰山祭祀或游览。历代帝王均来泰山举行封禅大典。；黄河与泰山是齐鲁大地独一无二的地理坐标。黄河与泰山古有“河岳”之并称。从古至今，泰山和黄河从文化的点、线、面多个维度互动，蕴含静与动、阳与阴、时间与空间、责任与信仰的多重意象。\n见证着华夏文明的形成和发展，映照出中华民族对和谐、安宁的千年追寻。主峰玉皇顶拔地而起，海拔1545米，如天柱般屹立。\n泰山并非寻常山岳，而是华北克拉通古老基底的脊梁，其岩体形成于25亿年前的新太古代，历经五次构造运动隆升，终成“五岳独尊”。\n地质上，泰山属于鲁西隆起带，而其北侧广袤的黄河下游平原则坐落在济阳坳陷之上，一隆一陷，一刚一柔。\n二者在构造上互为镜像：山为骨，河为脉；山主静，河主动；山守恒，河创生。正是这种地质上的张力与互补，塑造了齐鲁“山河表里、刚柔相济”的独特格局。', 117.108622, 36.257777, '泰安市泰山', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河与泰山同框_实景_03.jpg.jpg', NULL, '泰安', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(15, '黄河', '西晋时古黄河流经此地；陆机任平原内史时乘舟畅游黄河时做此诗，元吉降初巳。濯秽游黄河。此诗是诗人活动于德州黄河流域重要见证。', 116.307428, 37.453968, '德州市古黄河上', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/超然楼_实景_01.jpg', NULL, '德州', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(16, '无棣沟', '无棣沟，在今庆云县境内。史载春秋时齐国有无棣邑，隋朝置无棣县，唐代有古黄河流经。；无棣沟，是位于今河北省盐山县境内的一条古河道，古称无棣水（河），为清河支流，也是古黄河的支。其历史可追溯至春秋之前，春秋时即为齐国北部重要的鱼盐运输通道 。该河道在北朝魏时改称无棣沟。隋朝末年淤废，唐永徽元年（公元650年），沧州刺史薛大鼎曾主持疏浚以利鱼盐运输 。唐开元年间（公元723年）复经开挖。至元、明时期，无棣沟已基本湮灭。隋开皇六年（586年）置无棣县，即因县南临此沟而得名。', 117.38635, 37.77616, '德州市庆云县无棣沟', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/无棣沟-实景-01.jpg', NULL, '德州', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(17, '卫运河', '原为黄河故道，因春秋属卫地而得名，汉代称白沟。卫运河、南运河的前身为清河，为先秦黄河决流而成。历史上，卫河、卫运河、南运河是一条河，唐代称永济渠，宋代称御河。；卫运河（含卫河）上段是沟通河南、山东的重要航道，历史上大部分时间都为通航河段。是古黄河文化在德州重要见证。', 115.783929, 36.997776, '德州市夏津县卫运河', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/卫运河-实景-01.webp', NULL, '德州', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(18, '德州黄河号子', '起源可溯至明清至近代‌：德州因地处黄河故道与京杭大运河交汇处，船工拉纤、筑堤打硪（夯土）广泛使用号子协调劳作，\n形式分“开船号”“起锚号”“扛船号”“打硪号”等，具“一领众和”结构，曲调高亢质朴，如《三朵花》《落莲花》。\n‌清至民国持续发展‌：乾隆年间黄河治理工程中已有明确硪号记载；19世纪末至20世纪初，德州沿河（含齐河段）船工、\n硪工群体稳定传唱，内容含劳动指令与即兴俚语。\n‌20世纪中叶式微‌：1950–70年代，机械取代人力（如吸泥船“红心一号”1960年代启用、铁路航运兴起），拉纤与大硪集体劳动消失，号子实用功能消退，仅老匠人口传。\n‌2008年起系统保护‌：德州地区夯硪号子被纳入国家级非遗“黄河号子”（项目编号Ⅱ-133，含河南、山东多地）；2010年代起，德州市文化馆、齐河县河务局及非遗传承人（如郑福明）开展搜集、展演进校园。\n‌2022年正式命名“德州黄河号子”为市级非遗‌：明确以齐河沿黄区域为核心传承地，强调其区别于河南中牟等地的“打硪号子”，突出德州“河运+治黄”双重语境。‌；黄河号子是一种劳动号子，是船工和河工在劳动中喊唱的民间音乐形式 。2008年，黄河号子被公布为国家级非物质文化遗产。2021年11月，齐河县申报的传统音乐“黄河号子”入选山东省第五批省级非物质文化遗产代表性项目扩展名录。\n黄河号子采用一领众和的形式，节奏铿锵，情绪激昂，用以协调人力、鼓舞劳动情绪。按照劳动工种和场景，主要分为河工号子、夯硪号子和船工号子。黄河号子不仅有指挥劳动的实用价值，也以其优美的旋律、独特的韵味成为黄河文化的重要组成部分。\n黄河号子最早可追溯至春秋时期先民们在修堤夯土时发出的“杭”“育”之声，伴随着黄河治理与航运劳动而产生并传唱。据《宋史·河渠志》记载：“凡用丁夫数百或千人，杂唱齐挽，积置于卑薄之处，谓之‘埽岸’。”这种“杂唱”就是黄河号子。\n   黄河号子采用“一人领、众人和”的领和形式，其节奏铿锵，情绪激昂，曲调敦厚质朴、雄劲开阔、高亢有力。按照劳动工种和场景，主要分为河工号子、夯硪号子和船工号子。河工号子又可细分为骑马号、绵羊号、小官号、花号等不同腔调，以及捆枕号子、推枕号子、打桩号子、搂厢号子等工作号子。号子产生并服务于集体劳动，具有指挥劳动、协调动作、鼓舞士气、放松情绪、减缓劳动强度的实用价值。紧张型与舒缓型号子交替使用，能有效调节劳动强度。号词大多根据生活和生产中的经验、常识编排而成，熟练时可即兴创作，朗朗上口，易于传唱。其内容取材广泛，既包括抢险施工技术、河工生活逸事，也包含百姓喜闻乐见的戏文故事（如王侯将相、才子佳人），蕴含丰富的传统文化内涵和技术通俗性。号子以高亢、浑厚、雄壮、有力的节奏和声音，通过喊唱、齐唱、呼喊等表现形式，展现出协作一致、群情激昂的情绪与干劲，具有强烈的艺术感染力 。', NULL, NULL, '德州市齐河县', NULL, NULL, '德州', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(19, '德州黑陶', '德州黑陶历史沿革：新石器时代龙山文化起源 → 商周后失传 → 20世纪70年代末在德州复原 → 1980年代命名崛起 → 2009年获“中国黑陶城”称号 → 2014年烧制技艺列入国家级非遗。‌\n‌新石器时代晚期（约4500–4000年前）‌：属大汶口文化晚期至龙山文化时期，德州地区（如齐河、禹城等地）为龙山黑陶重要发祥地之一，以“蛋壳陶”（厚0.3–1.2毫米）为代表，具备“黑如漆、亮如镜、叩如磬”特征，采用快轮成型与封窑渗碳工艺，属祭祀礼器巅峰。\n‌商至汉代‌：随着青铜器与早期瓷器兴起，黑陶制作渐衰，至汉代基本失传。\n‌1928年‌：龙山文化因山东章丘城子崖遗址发掘被正式命名，但制作技艺仍未知；德州本地虽有黑陶残片出土（如尹屯、邢寨汪遗址），未形成连续传承。\n‌1970年代末‌：德州市工艺美陶研究所（前身为1979年芦庄黑陶厂）在王宪利、寇维军等艺人带领下，以京杭大运河红胶泥为原料，手工复原龙山黑陶技法，突破蛋壳陶成型与硬刻工艺。\n‌1986年‌：作品首次以“德州黑陶”名义在上海展出；1987年北京展览获谷牧题词“龙山新风”，引发全国黑陶热，作品被人民大会堂收藏并用作国礼。\n现代发展‌：在传统“11道工序”（选材、拉坯、压光、雕刻、渗碳烧制等）基础上，融合硬刻、微雕、无釉开片等创新，衍生茶具、香薰、艺术陈设等品类，持续推动非遗活化与文旅融合。‌；德州黑陶是中国黑陶的一种，因出土于山东省德州市而得名，属大汶口文化晚期至龙山文化时期的代表性陶器，\n距今约4000多年历史。其采用京杭大运河红胶泥为原料，经选材、拉坯、雕刻、烧制等11道工序制成，\n具有“黑如漆、亮如镜、叩如磬”的特征，表面可运用阴刻、镂空等技法形成纹理。德州是现代中国黑陶的发源地，\n是古代陶瓷的重要发源地之一，古代德州以发明“鬲”而闻名于世，称“有鬲氏”古代氏族部落以本部落发明而得名，\n如“神农氏”“有巢氏”等，德州又是古龙山文化的重要发源地之一，以黑陶为代表的龙山文化是1928年首先在山东\n章丘县龙山镇城子崖被发现，而中国首次发现的新文化类型以当地的地名命名，故山东黑陶得名龙山文化。在德州的齐河、\n禹城、乐陵、庆云、德城区发现这一时期的文化遗址有20多处德城区（在陈公堤口村西边铁路桥洞铁路东面北300米的水沟\n南侧发现）并出土了大量的文物有鬲、盆、罐、杯等，其中最典型的是被称为龙山文化典型代表的蛋壳陶杯（蛋壳陶手工在陶车上手拉坯制成，其厚0.3-1.2毫米，薄如蛋壳而得名），蛋壳陶杯是当时的最高级的祭祀礼器，也是古今拉坯制陶的最高水平，\n蛋壳陶的出现表示原始宗教的萌生，也是人类从渔猎走向农业，母系社会转向父系社会的象征。元、明、清到民国民间则以烧制\n民用生活用具为主。但在建筑用陶上则有很大发展，德州的官办砖窑则进贡到皇宫并做为长城用砖，窑址在今南郊窑上村始建于明\n洪武三十年，在德州出土的砖有明代的官司印，如“大明成化十七年德州造”“大明成化十九年德州造”“大明正德十年德州造”等。', NULL, NULL, '德州市', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/德州黑陶-实景-01.jpg', NULL, '德州', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
(20, '胡集书会', '胡集书会始于宋元、兴于明清，至今已有约800年历史，2006年被列入首批国家级非物质文化遗产名录，是中国北方现存最古老的民间曲艺交易集会之一。‌‌起源（宋元时期）‌：相传始于宋元，因胡集地处鲁北交通要道（近古黄河与大运河），商旅云集、民俗活跃，南北方说书艺人于每年正月十二大集自发汇聚“撂地卖艺、以书会友”，逐步形成年度惯例。‌发展与鼎盛（明清至清末民初）‌：明清时期随商品经济与运河商路繁荣，胡集成为鲁北重镇，“七十二店铺、钱庄十三家”，书会规模扩大，形成“前节（正月初一至十一）赶路、正节（正月十二至十六）卖场、偏节（十七至二十一）续雇”完整流程，西河大鼓、山东快书、琴书、评书等数十曲种齐聚，被誉为“一日看千台戏，三日读万卷书”。‌\n‌近代起伏（1930s–1970s）‌：抗日战争后渐趋萧条；1950年代初短暂复兴（年均300档艺人）；1958年“大跃进”及三年困难时期再陷低谷；1961–1966年小幅回升；“文革”期间受冲击但未中断；1978年改革开放后随农村经济复苏再度繁荣。；胡集书会是兴起于山东省惠民县胡集镇的国家级非物质文化遗产，起源于宋元时期曲艺艺人的竞技活动，迄今已有800余年历史，后逐渐演变为以联谊为主的自发性民间曲艺交易活动，活动流程分为前节（新年至正月十二前）、正节（正月十二至十六）和偏节（正月十七至二十一）三个阶段。每年农历正月十二，全国曲艺艺人汇集此地展演，涵盖评书、西河大鼓、山东快书等65个曲种。\n该活动于2006年列入首批国家级非物质文化遗产名录。1985年惠民县政府修建曲艺厅用于活动管理，2007年起实施“群众听书，政府买单”举措。2018年胡集镇获评“山东曲艺之乡”，2019年惠民县入选“中国曲艺之乡”。2023年惠民县文化馆重新被认定为项目保护单位。2025年书会开幕式发布专属标识及吉祥物“胡小艺”，活动增设全国美丽乡村曲艺展演等10项主题内容。', 117.736119, 37.331679, '惠民县胡集镇', 'https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/胡集书会-实景-02.webp', NULL, '滨州', '2026-06-17 18:00:50', '2026-06-17 18:00:50'),
